files.src/utils/url.test.ts:
import { path } from './url'

describe('path', () => {
  it('drops the query', () => {
    expect(path('/a?b')).toBe('/a')
  })
  it('drops the fragment', () => {
    expect(path('/a#b')).toBe('/a')
  })
})

files.src/utils/url.ts:
export function path(url: string): string {
  return url.split(/[?#]/)[0].replace(/\/+$/, '') || '/'
}

files.src/router/node.ts:
import { path } from '../utils/url'

export function match(route: string, raw: string): boolean {
  return route === path(raw)
}

files.src/router/node.test.ts:
import { match } from './node'

describe('match', () => {
  it('matches equal paths', () => {
    expect(match('/a', '/a')).toBe(true)
  })
  it('matches a trailing slash', () => {
    expect(match('/a', '/a/')).toBe(true)
  })
})
